export type ServerSettingsIconName = keyof typeof ICONS;

type IconProps = Omit<React.SVGProps<SVGSVGElement>, 'children' | 'dangerouslySetInnerHTML' | 'name'> & {
  name: ServerSettingsIconName;
  size?: number | string;
  title?: string;
  /** Ignore : icones pleines (compatibilite avec les props lucide). */
  strokeWidth?: number | string;
};

export function ServerSettingsIcon({ name, size = 24, title, strokeWidth: _strokeWidth, ...rest }: IconProps) {
  return (
    <svg
      viewBox="0 0 60 60"
      width={size}
      height={size}
      fill="none"
      role={title ? 'img' : undefined}
      aria-label={title}
      aria-hidden={title ? undefined : true}
      {...rest}
      dangerouslySetInnerHTML={{ __html: ICONS[name] }}
    />
  );
}
